import { reactive } from '@neuralfog/elemix';
import type { ActionState, FieldError } from './index';
import { ActionErrorKind, Method } from './index';

export type UserResponse = {
    id: string;
    name: string;
    handle: string;
};

export type ConflictAction = ActionState<UserResponse> & {
    run(): Promise<void>;
};

export const conflict = (): ConflictAction => {
    let controller: AbortController | null = null;
    return reactive<ConflictAction>({
        data: null,
        loading: false,
        isError: false,
        error: null,
        async run(): Promise<void> {
            controller?.abort();
            controller = new AbortController();
            const signal = controller.signal;
            this.data = null;
            this.error = null;
            this.isError = false;
            this.loading = true;
            try {
                const response = await fetch('/api/conflict', {
                    method: Method.Get,
                    signal,
                });
                if (response.ok) {
                    this.data = (await response.json()) as UserResponse;
                } else if (response.status === 400) {
                    const problem = (await response.json()) as {
                        errors: FieldError[];
                    };
                    this.error = {
                        kind: ActionErrorKind.Validation,
                        errors: problem.errors,
                    };
                    this.isError = true;
                } else {
                    this.error = {
                        kind: ActionErrorKind.Http,
                        status: response.status,
                    };
                    this.isError = true;
                }
            } catch {
                if (signal.aborted) return;
                this.error = { kind: ActionErrorKind.Network };
                this.isError = true;
            } finally {
                if (!signal.aborted) this.loading = false;
            }
        },
    });
};
